-- Seed N5 đầy đủ (Đợt bổ sung) — trích xuất từ 4 file PDF người dùng cung cấp:
--   "Tổng hợp kanji N5.pdf" (mindmap, 85 trang, 82 kanji)
--   "Tong-hop-tu-vung-N5.pdf" (bảng từ vựng, 39 trang, nguồn từ vựng chính)
--   "Từ vựng N5.pdf" (bảng từ vựng, 63 trang, nguồn từ vựng phụ)
--   "Tổng hợp ngữ pháp N5.pdf" (60 điểm ngữ pháp, 31 trang)
-- Bổ sung cho seed_content_n5.sql (file cũ chỉ có ~30 từ/15 kanji mẫu) — file này KHÔNG
-- thay thế, chỉ thêm phần còn thiếu. Đã loại trùng với 34 kanji + 254 từ đã có sẵn.
--
-- Giới hạn đã biết (do nguồn PDF không có các trường này, không tự bịa):
--   - Kanji mới: onyomi/kunyomi/stroke_count/han_viet/meaning_vi lấy từ kiến thức N5
--     chuẩn (không phải từ PDF), đối chiếu với dữ liệu từ ghép trong PDF để kiểm tra.
--     KHÔNG có mnemonic và stroke_data (SVG nét vẽ) — PDF nguồn không cung cấp, và
--     không tự tải dữ liệu KanjiVG ngoài phạm vi yêu cầu.
--   - Từ vựng mới: KHÔNG có part_of_speech, category, example_jp/example_vi — PDF
--     nguồn chỉ có word/reading/nghĩa, không có ví dụ câu hay phân loại từ loại.
--   - Một số entry trong PDF gốc có lỗi in ấn (furigana/nghĩa sai) — đã phát hiện và
--     sửa/loại bỏ thủ công trong lúc trích xuất, xem PROGRESS.md để biết chi tiết.
--
-- Chạy: supabase db query --linked -f supabase/seed_content_n5_full.sql
-- Idempotent: dùng UUID cố định (uuid5, namespace riêng cho batch này), on conflict an toàn.

