-- ─────────────────────────────────────────────────────────────
-- Ngữ pháp mới (60 điểm, bổ sung ngoài 54 điểm đã có)
-- ─────────────────────────────────────────────────────────────
insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
select v.id, v.title, v.explanation, v.example_jp, v.example_vi,
       (select id from jlpt_levels where code = 'N5')
from (values
  ('babe69ed-5246-58e4-a036-37d405ce7243'::uuid, '~は~', 'thì, là, ở. Phân cách chủ ngữ và vị ngữ trong câu. Thông tin truyền đạt thường đứng sau は. Làm chủ ngữ của mệnh đề chính. Chú ý: khi hỏi bằng は thì cũng trả lời bằng は, với thông tin trả lời thay thế cho từ để hỏi.', '私は日本の料理が好きです。', 'Tôi thích món ăn Nhật'),
  ('34273e89-35e5-5387-a92c-b96dd5217ae0'::uuid, '~も~', 'cũng, đến mức, đến cả. Dùng miêu tả sự vật/tính chất/hành động tương tự với một sự vật/tính chất/hành động đã nêu trước đó (nhằm tránh lặp lại trợ từ は/động từ nhiều lần). Thể hiện sự ngạc nhiên về mức độ nhiều. Thể hiện mức độ không giống như bình thường (cao hơn hoặc thấp hơn). Chú ý: も cũng có chức năng tương tự như は, が nên không đứng liền kề với は, が khi dùng cho một chủ từ. も cũng có thể đứng sau các trợ từ khác giống như は (で/と/へ/など も~).', '山田さんは本を読むことが好きです。私も同じです', 'Anh Yamada thích đọc sách. Tôi cũng vậy'),
  ('47485cae-93d4-5387-8367-dabda17d0ddb'::uuid, '~で~', 'tại, ở, vì, bằng, với (khoảng thời gian). Diễn tả nơi xảy ra hành động. Diễn tả nơi xảy ra sự kiện. Diễn tả nguyên nhân. Diễn tả phương pháp, phương thức, phương tiện. Diễn tả sự vật được làm bằng chất liệu/vật liệu gì. Diễn tả một khoảng thời gian giới hạn.', 'この仕事は明日で終りますか?', 'Công việc này sáng mai có xong không?'),
  ('836c10ff-b3f1-52d5-9dc5-404e0ffd93e2'::uuid, '~に/へ~', 'chỉ hướng, địa điểm, thời điểm. Dùng để chỉ thời điểm. Dùng để chỉ địa điểm. Dùng để chỉ hướng đến ai. Chú ý: khi muốn nói về một thời điểm mà hành động xảy ra, chúng ta thêm trợ từ [に] vào sau danh từ chỉ thời gian. Dùng に với những hành động diễn ra trong thời gian ngắn. [に] được dùng khi danh từ chỉ thời gian có con số đi kèm và không dùng trong trường hợp không có con số đi kèm; tuy nhiên với thứ trong tuần thì có thể dùng hoặc không dùng に. Khi động từ chỉ sự di chuyển thì trợ từ [へ] được dùng sau danh từ chỉ phương hướng hoặc địa điểm; trợ từ へ phát âm dài là [え].', '明日、旅行に/へ行きます。', 'Ngày mai tôi sẽ đi du lịch'),
  ('87f83460-102a-520f-a922-4477efbf4c04'::uuid, '~に~', 'vào, vào lúc. Khi muốn nói về một thời điểm mà hành động nào đó xảy ra, chúng ta thêm trợ từ「に」sau danh từ chỉ thời gian. Dùng「に」đối với những hành động xảy ra trong thời gian ngắn.「に」được dùng khi danh từ chỉ thời gian có con số đi kèm. Tuy nhiên, đối với trường hợp của thứ trong tuần thì có thể dùng hoặc không dùng「に」.', '7時に起きます。', 'Tôi thường thức dậy lúc 7h'),
  ('c568bcf9-a602-50e1-b52e-a2a8226210f4'::uuid, '~を~', 'chỉ đối tượng của hành động. Trợ từ「を」được dùng biểu thị bổ ngữ trực tiếp của ngoại động từ. Chú ý: phát âm của「を」giống「お」. Chữ「を」duy nhất chỉ được dùng làm trợ từ.', '水を飲みます。', 'Tôi uống nước'),
  ('05a684f6-6077-5c98-a6ad-d559f88c1cf6'::uuid, '~と~', 'với. Chúng ta dùng trợ từ「と」để biểu thị một đối tượng nào đó (người hoặc động vật) cùng thực hiện một hành động. Chú ý: trong trường hợp thực hiện hành động một mình thì dùng「ひとりで」, trường hợp này không dùng trợ từ「と」.', '公園に友達と散歩します。', 'Tôi đi dạo với bạn'),
  ('87f83460-102a-520f-a922-4477efbf4c04'::uuid, '~に~', 'cho ~, từ ~. Những động từ như「あげます」「かします」「おしえます」cần người làm đối tượng cho (để cho, cho mượn, dạy); chúng ta đặt trợ từ [に] sau danh từ chỉ đối tượng này. Đối với những động từ như「おくります」「でんわをかけます」thì đối tượng không chỉ là người mà còn có thể là địa điểm (danh từ); trong trường hợp đó ngoài trợ từ [に] chúng ta còn có thể dùng trợ từ [へ]. Các động từ như「もらいます」「かします」「ならいます」biểu thị hành động từ phía người tiếp nhận; khi chủ ngữ là người tiếp nhận thì thêm trợ từ [に] vào sau danh từ chỉ đối tác, và có thể dùng「から」thay cho [に]. Đặc biệt khi đối tác không phải là người mà là một tổ chức nào đó (công ty, trường học) thì không dùng [に] mà dùng「から」.', '山田さんは木村さんに花をあげました。', 'Anh Yamada tặng hoa cho chị Kimura'),
  ('05a684f6-6077-5c98-a6ad-d559f88c1cf6'::uuid, '~と~', 'và. Khi nối 2 danh từ với nhau thì dùng trợ từ「と」.', '野菜と肉を食べます。', 'Tôi ăn rau và thịt'),
  ('5164d278-2cee-5fac-ad5a-1db92164fac5'::uuid, '~が~', 'nhưng. 「が」là một trợ từ nối tiếp và có nghĩa là "nhưng". Khi dùng「が」để nối hai câu (mệnh đề) thì chúng ta được một câu. Khi muốn miêu tả một hiện tượng tự nhiên thì dùng「が」trước chủ đề đó. Chú ý:「が」dùng trong「しつれいですが」hoặc「すみませんが」để mở đầu một câu nói nên không còn mang ý nghĩa để nối hai câu, mà chỉ còn mang ý nghĩa nối tiếp mà thôi.', 'タイ料理はおいしいですが、辛いです。', 'Món Thái ngon nhưng cay.'),
  ('67144ddd-3226-5a16-988d-bf58ab714369'::uuid, '~から~まで~', 'từ ~ đến ~. 「から」biểu thị điểm bắt đầu của thời gian và địa điểm, còn「まで」biểu thị điểm kết thúc của thời gian và địa điểm.「から」và「まで」không nhất thiết phải đi kèm với nhau, mà còn có thể được dùng riêng biệt.', '9時から午後5時まで働きます。', 'Tôi làm việc từ 8h đến 5h chiều.'),
  ('7f7fded5-0305-5f11-9baf-e46c5baf2efa'::uuid, '~あまり~ない~', 'không ~ lắm. 「あまり」là phó từ biểu thị mức độ. Khi làm chức năng bổ nghĩa cho tính từ thì chúng được đặt trước tính từ. Khi làm chức năng bổ nghĩa cho động từ thì chúng được đặt trước động từ.', '私の日本語はあまり上手ではありません。', 'Tiếng Nhật của tôi không giỏi lắm'),
  ('4cb16502-c36e-56e0-910c-23417cc615fc'::uuid, '~全然~ない~', 'hoàn toàn ~ không. Là phó từ biểu thị mức độ. Khi làm chức năng bổ nghĩa cho động từ thì chúng được đặt trước động từ. Mang ý nghĩa hoàn toàn...không, luôn đi với câu phủ định. Chú ý:「全然」còn có thể dùng bổ nghĩa cho tính từ.', 'お金が全然ありません。', 'Tôi không có tiền.'),
  ('49b30190-ff03-516b-8799-bb35cd777263'::uuid, '~なかなか~ない~', 'mãi mà, mãi mới. Là phó từ biểu thị mức độ, khi làm chức năng bổ nghĩa cho động từ thì chúng được đặt trước động từ. Diễn tả ý để thực hiện một điều gì đó phải mất thời gian, sức lực, khó thực hiện.', 'なかなか寝ません。', 'Mãi mà không ngủ được.'),
  ('d451bf4b-29a9-5720-8075-d9ea9d2f7e95'::uuid, '~ませんか~', 'Anh/chị cùng ... với tôi không?. Mẫu câu này dùng để mời hoặc đề nghị người nghe cùng làm một việc gì đó.', 'いっしょに食べませんか?', 'Anh/chị đi ăn cùng tôi không?'),
  ('0661ae4e-8e39-5a41-86f9-1488b6629228'::uuid, '~があります~', 'Có (đồ vật). Mẫu câu này dùng để nói về nơi ở, sự hiện hữu của đồ vật. Những vật ở đây sẽ làm chủ ngữ trong câu, và được biểu thị bằng trợ từ「が」。「があります」dùng cho đối tượng không chuyển động được như đồ đạc, cây cối.', 'テーブルの上にコンピュータがあります', 'Có cái máy vi tính trên bàn'),
  ('f085451d-8485-5250-9c5a-d1c17ee79065'::uuid, '~がいます~', 'Có (con người, con vật). Mẫu câu này dùng để nói về nơi ở, sự hiện hữu của người, động vật. Người, động vật ở đây sẽ làm chủ ngữ trong câu, và được biểu thị bằng trợ từ「が」。「がいます」được dùng cho đối tượng có thể chuyển động được như người, động vật.', '女の子がいます。', 'Có cô gái'),
  ('ef906ac4-a8d6-5c5b-a870-6cab02edfa44'::uuid, '~動詞＋数量～', 'tương ứng với động từ chỉ số lượng. Thông thường thì lượng từ được đặt trước động từ mà nó bổ nghĩa, trừ trường hợp của lượng từ chỉ thời gian.', 'みかんを4つ買いました。', 'Tôi (đã) mua 4 quả cam'),
  ('5a0db655-791b-5d3a-b351-5fdbe3d61d77'::uuid, '~に~回~', 'Làm ~ lần trong khoảng thời gian. Diễn tả tần suất làm việc gì đó trong một khoảng thời gian.', '私は一月に2回映画を見ます。', 'Tôi xem phim 2 lần 1 tháng'),
  ('b1a4cdef-7402-5f4c-b14d-762aeedda1df'::uuid, '~ましょう~', 'chúng ta hãy cùng ~. Diễn tả sự thôi thúc cùng nhau làm việc gì đó. Chú ý: nằm trong mẫu câu thường dùng để rủ rê người nghe cùng làm việc gì đó.', 'ちょっと、休みましょう。', 'Cùng nghỉ một chút nhé')
) as v(id, title, explanation, example_jp, example_vi)
on conflict (id) do nothing;

insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
select v.id, v.title, v.explanation, v.example_jp, v.example_vi,
       (select id from jlpt_levels where code = 'N5')
from (values
  ('a9c7422b-28fc-5d9d-a5fa-2e21cbe64ba1'::uuid, '~ましょうか?~', 'Tôi ~ hộ cho anh nhé. Diễn tả sự xin phép để giúp đỡ người khác. Chú ý: dùng trong mẫu câu thường để rủ rê người nghe cùng làm việc gì đó.', '疲れました、ちょっと休みましょうか?', 'Mệt quá, nghỉ một chút không?'),
  ('2d624cff-6c4e-5027-a47b-957c9a0de43a'::uuid, '~がほしい~', 'Muốn. Mẫu câu này biểu thị ham muốn sở hữu một vật hoặc một người nào đó của người nói. Nó cũng được dùng để hỏi về ham muốn của người nghe. Đối tượng của ham muốn được biểu thị bằng trợ từ [が].「ほしい」là tính từ đuôi「い」. Chú ý: vì là tính từ đuôi い, nên phủ định của「ほしい」là「ほしくない」có nghĩa là không muốn. Mẫu câu không thể dùng để biểu thị ham muốn của người thứ ba. Mẫu câu không thể dùng để mời người nghe dùng một thứ gì hay làm gì; ví dụ muốn mời người nghe uống cà phê thì không nói [コーヒーが欲しいですか?] mà nói「コーヒーはいかがですか?」.', '私はお金がほしいです', 'Tôi muốn có tiền'),
  ('0a6e0bac-ec52-5a3e-9301-81bfd872f6d6'::uuid, '~たい~', 'Muốn làm... (V ます bỏ ます + たい). Đây là cách nói của sự "muốn làm" một cái gì đó. Cách nói này dùng để biểu thị ý muốn của bản thân người nói, và để hỏi về ý kiến của người nghe. Ngoài「を」thì không có trợ từ nào dùng thay thế「が」. Cách chia tương tự như tính từ đuôi「い」. Chú ý: mẫu câu「たいです」không thể dùng để biểu thị ham muốn của người thứ ba, và không thể dùng để mời người nghe dùng một thứ gì hay làm gì; ví dụ muốn mời người nghe uống cà phê thì không nói [コーヒーが飲みたいですか?] mà nói「コーヒーが飲みませんか?」.', '日本へ行きたいです。', 'Tôi muốn đi Nhật'),
  ('eb63ca7d-33f3-5614-89c5-1ccdd32fae7c'::uuid, '~へ~を~に行く', 'Đi đến....để làm gì. Động từ ở thể [ます] hoặc danh từ đặt trước trợ từ [に] biểu thị mục đích của「いきます」. Danh từ đặt trước [に] phải là danh từ chỉ hành động. Chú ý: có thể đặt trước [に] các danh từ chỉ sự việc được tổ chức ra như lễ hội, buổi hòa nhạc; trong trường hợp này thì mục đích của người nói là xem lễ hội, nghe nhạc v.v...', '日本へ文化の勉強に来ました。', 'Tôi đi đến Nhật để học văn hóa'),
  ('c96bd43c-9d9f-58ea-949a-b326bcad2329'::uuid, '~てください~', 'Hãy. Mẫu câu này được dùng khi người nói muốn nhờ vả, sai khiến hoặc khuyên nhủ người nghe. Khi nói với người trên thì không dùng mẫu này với ý sai khiến. Chú ý: khi đề nghị ai làm việc gì,「すみませんが」luôn đặt trước ～てください như trong ví dụ 1, như vậy sẽ lịch sự hơn trường hợp chỉ dùng ～てください.', 'すみませんが、この漢字の読み方を教えてください。', 'Xin lỗi, hãy chỉ cho tôi cách đọc chữ kanji này.'),
  ('40bdac0c-56b6-57e3-907e-7e3d616df997'::uuid, '~ないでください~', '(xin) đừng / không. Mẫu câu này được dùng khi muốn yêu cầu ai đó đừng làm một việc gì đó.', '私は元気ですから、心配しないでください', 'Vì tôi khỏe nên đừng lo cho tôi'),
  ('3fbc7ac3-af15-5da8-8378-aa33cfca625b'::uuid, '~てもいいです~', 'Làm ~ được. Mẫu câu này dùng để biểu thị sự được phép làm một điều gì đó. Nếu mẫu câu này thành câu nghi vấn thì chúng ta sẽ được một câu xin phép. Khi trả lời thì chú ý cách trả lời tế nhị khi từ chối.', '本を読んでもいいです。', 'Được phép đọc sách (ở đây)'),
  ('c6ddf09c-6861-5f34-95d9-f9c60995e946'::uuid, '~てはいけません~', 'Không được làm ~. Mẫu câu này biểu thị ý nghĩa "cấm" hay "không được" làm một việc gì đó. Dùng để trả lời cho câu hỏi [Động từ thể てもいいですか?]. Chú ý: đối với câu hỏi [Động từ thể てもいいですか?], khi muốn nhấn mạnh câu trả lời không được thì có thể lược bỏ [Động từ thể ては] mà chỉ trả lời là「いいえ、いけません」; cách trả lời này không dùng với người trên.', 'ここで車に止めてはいけません。駐車禁止ですから。', 'Không được đậu xe ở đây. Vì đây là khu vực cấm đậu xe.'),
  ('2e2ea440-9b42-59d4-8dc7-4be409359ac3'::uuid, '~なくてもいいです~', 'Không phải, không cần ~ cũng được. Mẫu câu này biểu thị rằng một đối tượng nào đó không phải làm một việc gì đó.', '明日来なくてもいいです。', 'Ngày mai anh không đến cũng được'),
  ('be07cc26-e73e-57f9-815a-a7ad7ea5675b'::uuid, '~なければなりません~', 'Phải ~. Mẫu câu này biểu thị rằng một đối tượng nào đó phải làm một việc gì đó mà không phụ thuộc vào ý muốn của đối tượng thực hiện hành động. Lưu ý là mẫu câu này không mang ý nghĩa phủ định.', '薬を飲まなければなりません。', 'Tôi phải uống thuốc'),
  ('291620a5-e4ec-5a16-a8f8-e7f1aa567179'::uuid, '~ないといけない~', 'Phải ~. Động từ ở thể「ない」ghép với「といけない」. Chú ý: có thể dùng mẫu câu này để đặt câu hỏi "cần phải...".', '英語でレポートを書かないといけない。', 'Tôi phải viết báo cáo bằng tiếng Anh'),
  ('34d2167f-9374-5d34-a402-bdd913a1941c'::uuid, '~なくちゃいけない~', 'Không thể không (phải). Động từ thể ない bỏ い thay bằng なくちゃいけない, có nghĩa cần thiết phải làm gì đó. Chú ý: mẫu câu này tương đương mẫu câu なくてはいけない, tuy nhiên người ta sử dụng なくちゃいけない để biểu đạt trong văn nói.', '食べなくちゃいけない。', 'Tôi phải ăn'),
  ('864c47fe-5009-5183-b55d-619ea5418d32'::uuid, '~だけ~', 'Chỉ ~. Diễn tả ý nghĩa ngoài điều đó ra thì không còn điều nào khác. Ngoài ra còn diễn tả ý nghĩa phủ định「だけでなく」(không còn).', 'あなただけにお知らせします。', 'Tôi chỉ cho một mình anh biết mà thôi'),
  ('414df9f6-606f-5584-a2ef-3b72b999f769'::uuid, '~から~', 'Vì ~. Được dùng để nối hai câu thành một câu. Câu 1 biểu thị lý do cho câu 2. Cũng có thể nối 2 câu trước, sau đó nối câu 1 kèm theo「から」.', '朝忙しいですから、朝ごはんを食べません。', 'Vì buổi sáng bận quá nên tôi không ăn sáng'),
  ('3d3b2bfd-7c35-59a5-b69b-6726924b3cf5'::uuid, '~のが~', 'Danh từ hóa động từ. Trong mẫu câu này thì các tính từ chỉ sở thích, kỹ năng, năng lực, ví dụ như すてき(な)、きらい(な)、じょうず「な」、へた「な」、はやい、おそい... được dùng.', '私は音楽を聞くのがすきです', 'Tôi thích nghe nhạc'),
  ('f777f0b8-312f-5912-9b97-e95bfdb1a811'::uuid, '~のを~', 'Danh từ hóa động từ. Diễn tả danh từ hóa động từ với động từ わすれました sẽ sử dụng thể nguyên dạng (辞書形), có nghĩa là quên. Diễn tả danh từ hóa động từ với động từ 知っていますか?sẽ sử dụng thể thông thường (普通形), có nghĩa là Anh biết...không? Mẫu câu dùng để hỏi xem người nghe có biết được nội dung được biểu thị ở phần trước không?', '薬を買うのを忘れました。', 'Tôi quên mua thuốc'),
  ('6b7c7e2c-f0b3-525a-9d31-9fded6659116'::uuid, '~のは~', 'Danh từ hóa động từ. Mẫu câu này,「の」dùng để thay thế danh từ biểu thị đồ vật, người, địa điểm v.v... để nêu ra chủ đề của câu.', '1年で一番雨が多いのは8月です。', 'Tháng mưa nhiều nhất trong năm là tháng 8.'),
  ('11e55bb3-1e8a-525b-bea7-f0c25d43e8b0'::uuid, '~もう~ました~', 'Đã làm gì ~. Diễn tả hành động đã hoàn thành.', 'もう宿題をしましたか?', 'Đã làm bài tập xong chưa?'),
  ('3f9e2a82-420e-530a-af81-b63670dd8bf2'::uuid, '~まだ~ていません。', 'Vẫn chưa làm ~. Diễn tả một hành động chưa hoàn thành nhưng có ý định sẽ làm.', 'ご飯を食べましたか?いいえ、まだ食べていません。', 'Ăn cơm chưa? Vẫn chưa ăn'),
  ('b3f5eec8-1e15-5a7b-ad6d-bf5bdb62acc7'::uuid, '~より~', 'So với.... Diễn tả sự so sánh. Chú ý: N1 は N2 より không dùng cho tính từ ở dạng phủ định; nếu muốn phủ định thì dùng tính từ ngược nghĩa chứ không dùng thể phủ định của tính từ.', '日本はベトナムより大きいです。', 'Nhật Bản lớn hơn Việt Nam')
) as v(id, title, explanation, example_jp, example_vi)
on conflict (id) do nothing;

insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
select v.id, v.title, v.explanation, v.example_jp, v.example_vi,
       (select id from jlpt_levels where code = 'N5')
from (values
  ('ee0cb88a-1cb1-57a6-ab2c-513f5e2d706d'::uuid, '~ほど~ない~', 'Không ... bằng. Thể hiện ý lấy N2 làm chuẩn để so sánh thì N1 không bằng N2.', 'ベトナムは日本ほど寒くない。', 'Việt Nam không lạnh bằng Nhật Bản'),
  ('eb7676e8-e51c-5262-8d40-3efd974b32b0'::uuid, '~と同じ~', 'Giống với ~, tương tự với ~. Diễn tả hai thứ giống nhau cả về bản chất và hình thức.', 'この本はあの本と出版社が同じだ。', 'Cuốn sách này cùng nhà xuất bản với cuốn sách kia.'),
  ('c0c4818f-0258-5897-aadc-f102688da4b2'::uuid, '~のなかで～がいちばん～', 'Trong số ... nhất. Dùng để chỉ ra phạm vi so sánh từ 3 vật trở lên.', '季節の中で、春が一番好きです。', 'Trong các mùa trong năm, tôi thích nhất là mùa xuân.'),
  ('a8cd75af-775d-5276-b093-d93200a4709c'::uuid, '~く/~になる~', 'Trở thành, trở nên. Diễn tả một hành vi trong tương lai sẽ phát sinh một kết quả nào đó.', '今年の7月に博士になります。', 'Vào tháng 7 này tôi sẽ trở thành thạc sĩ.'),
  ('6fbb8fd5-792a-5eed-beb3-bc281734802a'::uuid, '~も~ない~', 'Cho dù ~ cũng không. Mẫu câu này biểu thị điều kiện ngược, dùng khi một hành động nào đó trong một hoàn cảnh nhất định đáng ra phải làm nhưng lại không làm, một việc nào đó đáng ra phải xảy ra nhưng lại không xảy ra, hoặc một kết quả trái với quan niệm thông thường của mọi người.', '安くても、買いません。', 'Cho dù giá rẻ tôi cũng không mua.'),
  ('001dda56-7a1a-5e9c-99ea-6a092f478601'::uuid, '~たり。。。～たりする', 'Làm ~ làm, và ~. Dùng để liệt kê nhiều hành động hay tính chất của sự vật.', '私は歩かったり、音楽を聞かったりする好きです。', 'Tôi thích đi bộ và nghe nhạc'),
  ('765675e4-cfb0-5f75-b558-378d7d4187e4'::uuid, '~ている~', 'Vẫn đang. Diễn tả một hành động đang diễn ra. Diễn tả về một trạng thái (là kết quả của một hành động) vẫn còn lại, vẫn tiếp tục ở hiện tại. Dùng để nói về các tập quán, thói quen (những hành vi được lặp đi lặp lại trong một thời gian dài); nếu là thói quen hay hành vi trong quá khứ thì dùng thể「ていました」. Dùng để nói về nghề nghiệp hay tình cảnh của ai đó. Chú ý: chúng ta dùng mẫu câu này để trả lời khi được hỏi「おしごとはなんですか?」.', '日本語を勉強している。', 'Tôi đang học tiếng Nhật'),
  ('5654b8db-adca-5d0d-bd8a-08eedcf0ca4e'::uuid, '~ることがある~', 'Có khi, thỉnh thoảng. Diễn tả một sự việc xảy ra không có tính thường xuyên, lâu lâu, thỉnh thoảng mới xảy ra.', '映画を見ることがありませんか?', 'Bạn có thường xem phim không?'),
  ('19fd0c7b-94de-550d-b13e-a34b6c61dee8'::uuid, '~ないことがある~', 'Có khi nào không....?. Diễn tả sự việc xảy ra không có tính thường xuyên, lâu lâu, thỉnh thoảng mới xảy ra (dạng phủ định).', '朝ごはんを食べないことがありますか?', 'Bạn có khi nào không ăn sáng không?'),
  ('24db2e94-d6ab-5c1e-8762-8c5c4e336a9a'::uuid, '~たことがある~', 'Đã từng. Dùng để chỉ một hành động đã từng xảy ra trong quá khứ. Chú ý: trường hợp muốn thể hiện câu hỏi với ý "anh/chị đã ~ từng chưa?" thì ta thêm trợ từ [か] vào sau mẫu câu.', 'やはしさんにはこれまでに2度お会いしたことがあります。', 'Tính đến giờ thì tôi đã gặp Yahashi 2 lần rồi.'),
  ('449e4ae7-8b67-52b2-812b-420505001a4f'::uuid, '~や~など', 'Như là...và.... Trợ từ「や」được dùng khi chúng ta muốn liệt kê các danh từ. Trợ từ「や」được dùng để liệt kê một số đối tượng tiêu biểu (hai danh từ trở lên) mà thôi. Chúng ta có thể dùng trợ từ「など」ở cuối danh từ để biểu thị rõ rằng có những đối tượng khác ngoài đối tượng được nêu.', '机の上に本やペンなどがあります。', 'Trên bàn có sách và viết'),
  ('1b552490-7571-516b-b2dc-36a7dbc7860e'::uuid, '~ので~', 'Bởi vì ~. Diễn tả lý do khách quan, tự nhiên, tất nhiên dẫn đến như thế. Khi sử dụng「ので」sẽ thể hiện cách nói nhẹ nhàng, mềm mại nên sẽ không dùng đến phần sau của câu ở thể mệnh lệnh hay cấm chỉ. Chú ý: phân biệt giữa「ので」và「から」:「ので」dùng nêu lên lý do mang tính khách quan,「から」dùng nêu lên lý do mang tính chủ quan.', '雨が降りそうなので試合は中止します。', 'Vì trời sắp mưa nên trận đấu sẽ dời lại'),
  ('92d9ba87-b8cb-5da4-baa9-e008061235bf'::uuid, '~まえに~', 'trước khi ~. Trường hợp của động từ: mẫu câu này biểu thị rằng động tác ở động từ 2 xảy ra trước động tác ở động từ 1. Động từ 1 luôn ở thể nguyên dạng, cho dù động từ 2 có ở thì quá khứ hoặc tương lai. Trường hợp của danh từ: khi dùng「まえに」sau danh từ thì chúng ta phải thêm「の」vào ngay sau danh từ; danh từ ở trước「まえに」là danh từ biểu thị hoặc ám chỉ động tác. Trường hợp của lượng từ (khoảng thời gian): nếu là lượng từ (khoảng thời gian) thì không thêm「の」.', '私のまえに砂糖さんが座っていた。', 'Ngồi phía trước tôi là chị Sato'),
  ('17d5e613-034f-5c28-b921-6cac9a82b059'::uuid, '~てから', 'Sau khi ~, từ khi ~. Mẫu câu này dùng để biểu thị rằng hành động ở động từ 2 được thực hiện sau khi hành động ở động từ 1 kết thúc. Thời của câu do thời của động từ cuối quyết định. Chú ý: đối với chủ ngữ của mệnh đề phụ, động từ đứng sau là động từ chỉ hành động.', '夏休みになってから一度も学校に行っていない。', 'Từ khi nghỉ hè tôi chưa lần nào đến trường'),
  ('0fb13e20-3af9-5269-9862-f7b6d0c99ade'::uuid, '~たあとで', 'Sau khi ~. Mẫu câu này dùng để diễn tả sự việc được thể hiện ở động từ 2 sau khi sự việc được biểu thị ở động từ 1 xảy ra. Chú ý: so với「Động từ thể てから」thì mẫu câu này thể hiện rõ hơn trình tự thời gian trước sau của sự việc.', 'この本、あなたが見たあとで、私にも貸してください。', 'Sau khi bạn đọc xong cuốn sách này thì cho tôi mượn nhé'),
  ('2eab616d-84b1-59fa-962c-6e70cbb69fe7'::uuid, '~とき', 'Khi ~. Diễn tả một trạng thái hay một sự việc diễn ra đồng thời. V-る時 (trước) khi: hành động ở vế sau xảy ra trước hành động ở vế trước. V-た時 (sau) khi: sau khi một động tác được thực hiện thì một sự việc khác mới xảy ra.', '暇な時は、どんなことをして過ごしますか?', 'Lúc rảnh bạn thường làm gì?'),
  ('45fa9d08-7db9-5a8b-adde-219509b28c13'::uuid, '~でしょう?~', '~ đúng không?. Chắc chắn là ~ phải không? Được dùng với giọng cao hơn để xác nhận sự đồng ý của người nghe khi người nói nghĩ là người nghe có sự hiểu biết về chủ đề câu chuyện, và kỳ vọng là người nghe sẽ đồng ý với ý kiến của mình.', 'あなたは、学生さんでしょうか?', 'Bạn là sinh viên, đúng không?'),
  ('a42d66a4-9dc8-5cc9-8322-13ce5d4802ca'::uuid, '~多分～でしょう~', 'Chắc hẳn là ~, có lẽ ~. Dùng khi người nói nhận thấy khả năng chắc chắn 90% trở lên.', '多分その本はおもしろいでしょう!', 'Cuốn sách kia chắc là hay lắm.'),
  ('738d780d-cb0c-5da4-86b6-32bf35566022'::uuid, '~と思います', 'Tôi nghĩ rằng. Chúng ta sử dụng trợ từ「と」để biểu thị nội dung của「おもいます」. Dùng để biểu thị sự suy đoán, phán xét; khi phán đoán, suy xét về một nội dung mang ý nghĩa phủ định thì phần trước「と」sẽ là phủ định. Dùng để bày tỏ ý kiến. Khi muốn hỏi ai đó về một cái gì đó thì dùng mẫu câu「～についてどうおもいますか」và chú ý không cần「と」ở sau「どう」. Cách biểu thị sự đồng ý hoặc không đồng ý với người khác.', '今日は雨が降らないと思います。', 'Tôi nghĩ là hôm nay trời sẽ không mưa.'),
  ('06ff9c8c-127c-5157-9b8c-03c887303336'::uuid, '~と言います', 'Nói ~. Chúng ta dùng trợ từ「と」để biểu thị nội dung của「いいます」. Khi trích dẫn trực tiếp thì ta để nguyên phần trích dẫn đó và cho vào trong「」. Khi trích dẫn gián tiếp thì chúng ta dùng thể thông thường ở trước「と」. Thời của phần trích dẫn không phụ thuộc vào thời câu.', 'ご飯を食べるまえに「いただきます」といいました。', 'Trước khi ăn thì thường nói [chúc mọi người ngon miệng]')
) as v(id, title, explanation, example_jp, example_vi)
on conflict (id) do nothing;

-- Patch: PDF gốc có 2 điểm ngữ pháp #8 và #9 trùng title với #5 và #7 ("~に~",
-- "~と~" — 4 cách dùng khác nhau nhưng chỉ 2 tên mẫu câu). uid tính theo title ở
-- trên khiến #8/#9 bị "on conflict do nothing" bỏ qua nhầm. Bổ sung lại với id
-- cố định riêng.
insert into grammar_points (id, title, explanation, example_jp, example_vi, level_id)
select v.id, v.title, v.explanation, v.example_jp, v.example_vi,
       (select id from jlpt_levels where code = 'N5')
from (values
  ('a1b2c3d4-0000-4000-8000-000000000008'::uuid, '~に~',
   'cho ~, từ ~. Những động từ như「あげます」「かします」「おしえます」cần người làm đối tượng cho (để cho, cho mượn, dạy); chúng ta đặt trợ từ [に] sau danh từ chỉ đối tượng này. Đối với những động từ như「おくります」「でんわをかけます」thì đối tượng không chỉ là người mà còn có thể là địa điểm (danh từ); trong trường hợp đó ngoài trợ từ [に] chúng ta còn có thể dùng trợ từ [へ]. Các động từ như「もらいます」「かします」「ならいます」biểu thị hành động từ phía người tiếp nhận; khi chủ ngữ là người tiếp nhận thì thêm trợ từ [に] vào sau danh từ chỉ đối tác, và có thể dùng「から」thay cho [に]. Đặc biệt khi đối tác không phải là người mà là một tổ chức nào đó (công ty, trường học) thì không dùng [に] mà dùng「から」.',
   '山田さんは木村さんに花をあげました。', 'Anh Yamada tặng hoa cho chị Kimura'),
  ('a1b2c3d4-0000-4000-8000-000000000009'::uuid, '~と~',
   'và. Khi nối 2 danh từ với nhau thì dùng trợ từ「と」.',
   '野菜と肉を食べます。', 'Tôi ăn rau và thịt')
) as v(id, title, explanation, example_jp, example_vi)
on conflict (id) do nothing;
